"""Seal evidence only after complete parity. Does not activate the candidate."""
import json, hashlib, pathlib, statistics
H=pathlib.Path(__file__).resolve().parent
ROOT=next(p for p in H.parents if (p/'world_city').is_dir())
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def read(name):return json.loads((H/name).read_text())
p=read('full_boundary_parity.json');proof=read('proof_report.json')
assert p['status']=='pass' and not p['failures'] and p['queries']==p['expected_queries']==1114007
assert proof['status']=='pass_frozen_data_and_predicate_invariants'
bench=[read(n+'.json') for n in ['original_fresh_1','prefilter_fresh_1','prefilter_fresh_2','original_fresh_2']]
assert all(v['status']=='pass' and v['queries']==v['expected_queries']==20000 for v in bench)
assert len({v['output_digest_sha256'] for v in bench})==1
for result in [p]+bench:
 for name,h in result['inputs'].items():assert sha(ROOT/name)==h,name
assert proof['candidate_sha256']==sha(H/'prefilter.py')
assert proof['binding_sha256']==sha(H/'candidate_binding.json')
old=[v['query_wall_seconds'] for v in bench if v['mode']=='original'];new=[v['query_wall_seconds'] for v in bench if v['mode']=='prefilter']
files=['prefilter.py','candidate_binding.json','prepare.py','fixtures.json','run.py','prove_prefilter.py','proof_report.json','full_boundary_parity.json','original_fresh_1.json','prefilter_fresh_1.json','prefilter_fresh_2.json','original_fresh_2.json','finalize.py']
report=dict(schema='riverstone.owner_query_prefilter_review.v1',status='pass_bounded_lookup_candidate',activation='Not activated in a scene or export; explicit OwnerLookup object only.',proof=proof,boundary_parity={k:p[k] for k in ['queries','expected_queries','output_digest_sha256','query_wall_seconds','query_cpu_seconds','failures']},benchmarks=bench,median_query_ratio=statistics.median(old)/statistics.median(new),evidence=[dict(path=str((H/n).relative_to(ROOT)),sha256=sha(H/n)) for n in files],limits=['Exact rejection implication plus exhaustive selected boundary samples; not a general performance guarantee.','Original sorted 32 m index, boundary tolerance, polygon predicate, first-owner selection and fallback remain unchanged.','All original owner dictionaries and index must remain immutable for the lifetime of this explicitly instantiated object.','Fresh-process point-query microbenchmarks only. Import, preparation and full export costs are separate.','No retaining-interface adjacency skips, current export changes, scene approval or traversal claim.'])
out=H/('review_'+sha(H/'prefilter.py')[:12]+'.json');out.write_text(json.dumps(report,indent=2)+'\n')
(H/'README.md').write_text('''# Conservative owner-query candidate\n\nStatus: passed the bounded lookup review. The candidate is not activated in any export or scene.\n\n## Result\n\n- 24,996 original owner records and their original sorted 32 m candidate index are preserved.\n- 1,114,007 direct owner comparisons passed, including every unique source vertex, every unique source edge midpoint at five signed offsets, and 20,000 deterministic workload points.\n- Two fresh-process 20,000-point trials per implementation produced identical owner-result digests. See the sealed review for measured query, import and preparation times. These timings do not predict whole-export acceleration.\n\n## Why rejection is conservative\n\nThe bounding box chooses existing polygon edges to check; the box itself never decides that a point is outside. The selected edge has exactly the same endpoints, orientation, length, arithmetic expression and tolerance as the original point-in-convex-polygon predicate. If that edge rejects, the full original predicate must reject too. Otherwise, the unchanged full original predicate executes. Consequently, skipping only these proved-false records preserves the first accepted record, including priority ties and near-boundary tolerance behavior.\n\nThe constructor binds the upstream module bytes, geometry helper bytes and complete ordered owner dictionaries. Precomputed values require these sealed records and the index to remain immutable during use. It returns the original owner dictionary objects and keeps the same fallback and 262,144-entry per-object LRU contract.\n\n## Explicit use\n\nImport `OwnerLookup` from `prefilter.py`, create `OwnerLookup(upstream)`, then call its `lookup(x,z)` for uncached queries or `owner_at(x,z)` for the matching LRU behavior. The object does not install itself, mutate the source module, change any sealed source file, or alter the current export. Any exporter integration needs its own explicit binding.\n\n## Reproduction\n\nRun `prepare.py` to reproduce fixtures only when not preserving the sealed evidence. Run `run.py original LABEL` and `run.py prefilter LABEL` in separate fresh Python processes. `run.py parity LABEL` compares full selected boundary/workload fixtures. `prove_prefilter.py` checks the source-predicate and prepared-edge invariants. `finalize.py` refuses to seal incomplete or mismatched results.\n\nThis candidate does not skip adjacency or retaining-interface work. The earlier rejected fast-interface helper remains separate failed evidence. No terrain ownership change or traversal approval follows from this lookup review.\n''')
print(out.relative_to(ROOT),sha(out))
print('median query ratio',report['median_query_ratio'])
